import pytest
from solution import to_camel_case


def test_basic_snake_case():
    assert to_camel_case("hello_world") == "helloWorld"
    assert to_camel_case("foo_bar_baz") == "fooBarBaz"


def test_basic_kebab_case():
    assert to_camel_case("hello-world") == "helloWorld"
    assert to_camel_case("foo-bar-baz") == "fooBarBaz"


def test_mixed_separators():
    assert to_camel_case("snake_case-kebab_case") == "snakeCaseKebabCase"


def test_single_word_no_separator():
    assert to_camel_case("hello") == "hello"
    assert to_camel_case("Hello") == "Hello"


def test_first_word_case_preserved():
    assert to_camel_case("Foo_bar") == "FooBar"
    assert to_camel_case("foo_Bar") == "fooBar"


def test_subsequent_words_original_case_preserved():
    assert to_camel_case("foo_bAR_baz") == "fooBARBaz"
    assert to_camel_case("foo-BaR-baz") == "fooBaRBaz"


def test_digits_in_words():
    assert to_camel_case("foo_2_bar") == "foo2Bar"
    assert to_camel_case("version_1_2_3") == "version123"


def test_unicode_letters():
    assert to_camel_case("café_au_lait") == "caféAuLait"
    assert to_camel_case("naïve-approach") == "naïveApproach"


def test_long_identifier():
    assert to_camel_case("this_is_a_very_long_identifier_with_many_words") == "thisIsAVeryLongIdentifierWithManyWords"


def test_leading_digit():
    assert to_camel_case("1st_place") == "1stPlace"
    assert to_camel_case("2nd-place") == "2ndPlace"
